export function mapAntigravityUsage(
  body: AntigravityResponse,
  nowMs: number,
): QuotaUsageSnapshot | null {
  if (body == null || typeof body !== "object") return null;
  const infos = (body.models ?? [])
    .map((m) => m.quotaInfo)
    .filter((q): q is { remainingFraction: number; resetTime?: string | null } =>
      !!q && typeof q.remainingFraction === "number",
    );
  if (infos.length === 0) return null;
  const binding = infos.reduce((a, b) => (b.remainingFraction < a.remainingFraction ? b : a));

export function mapCodexUsage(body: CodexUsageResponse, nowMs: number): QuotaUsageSnapshot | null {
  if (body == null || typeof body !== "object") return null;
  const rl = body.rate_limit;
  const windows = [rl?.primary_window, rl?.secondary_window].filter(
    (w): w is CodexWindow => !!w && typeof w.used_percent === "number",
  );
  if (windows.length === 0) return null;
  const binding = windows.reduce((a, b) => (b.used_percent! > a.used_percent! ? b : a));

