function dedupeTasks<T extends { task_id: string }>(tasks: T[]): T[] {
  const seen = new Set<string>();
  const deduped: T[] = [];
  for (const task of tasks) {
    if (seen.has(task.task_id)) {
      continue;
    }
    seen.add(task.task_id);
    deduped.push(task);
  }
  return deduped;
}

