function dedupeByScope<T extends { lens: string; file_paths: string[] }>(
  tasks: T[],
): T[] {
  const seen = new Set<string>();
  const deduped: T[] = [];

  for (const task of tasks) {
    const signature = `${task.lens}:${[...task.file_paths].sort().join(",")}`;
    if (seen.has(signature)) {
      continue;
    }
    seen.add(signature);
    deduped.push(task);
  }

  return deduped;
}

