export function buildTestFileIndex(root: string): TestFileEntry[] {
  const index: TestFileEntry[] = [];
  for (const testPath of walkTestFiles(root)) {
    let content: string;
    try {
      content = readFileSync(testPath, "utf8");
    } catch {
      continue;
    }
    index.push({ rel: relative(root, testPath).replace(/\\\/g, "/"), content });
  }
  return index;
}

async function withEnvParity<T>(fn: () => Promise<T>): Promise<T> {
  const hadClaudecode = Object.prototype.hasOwnProperty.call(process.env, "CLAUDECODE");
  const prevClaudecode = process.env.CLAUDECODE;
  delete process.env.CLAUDECODE;
  try {
    return await fn();
  } finally {
    if (hadClaudecode) process.env.CLAUDECODE = prevClaudecode;
  }
}

function intersection(a: readonly string[], b: readonly string[]): string[] {
  const shared: string[] = [];
  let left = 0;
  let right = 0;
  while (left < a.length && right < b.length) {
    const comparison = a[left]!.localeCompare(b[right]!);
    if (comparison === 0) {
      shared.push(a[left]!);
      left += 1;
      right += 1;
    } else if (comparison < 0) {
      left += 1;
    } else {
      right += 1;
    }
  }
  return shared;
}

function jaccard(a: readonly string[], b: readonly string[]): number | null {
  if (a.length === 0 || b.length === 0) return null;
  let shared = 0;
  let left = 0;
  let right = 0;
  while (left < a.length && right < b.length) {
    const comparison = a[left]!.localeCompare(b[right]!);
    if (comparison === 0) {
      shared += 1;
      left += 1;
      right += 1;
    } else if (comparison < 0) {
      left += 1;
    } else {
      right += 1;
    }
  }
  return shared / (a.length + b.length - shared);
}

